<script setup lang="ts">
import {ref,onUnmounted} from 'vue';import {accessToken} from './extensions/identity';import {call} from './api';import {documentContract as c} from './document-contract';
type Doc={documentId:string;filename:string;mediaType:string;size:number;sha256:string;createdAt:string};
const resource=ref(''),file=ref<File|null>(null),rows=ref<Doc[]>([]),busy=ref(false),status=ref(''),error=ref('');let pending:{key:string;file:File;resource:string}|null=null;let epoch=0;
function reset(){epoch++;rows.value=[];error.value='';status.value='';pending=null;busy.value=false;}
onUnmounted(()=>{epoch++});
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]??null;pending=null;}
async function list(){const run=++epoch;busy.value=true;error.value='';try{const r=await call<{items:Doc[]}>(c.path+'/list',{resourceId:resource.value,page:0,size:20});if(!Array.isArray(r?.items))throw Error();if(run===epoch)rows.value=r.items;}catch{if(run===epoch){rows.value=[];error.value='Documents unavailable or access denied';}}finally{if(run===epoch)busy.value=false;}}
async function upload(){error.value='';if(!file.value||!file.value.name.endsWith('.txt')||file.value.type!=='text/plain'||file.value.size<1||file.value.size>c.maximumBytes){error.value='Choose a permitted nonempty text document within the size limit';return;}
 if(!pending||pending.file!==file.value||pending.resource!==resource.value)pending={key:crypto.randomUUID(),file:file.value,resource:resource.value};const attempt=pending;const run=++epoch;busy.value=true;status.value='Uploading document';
 try{const raw=await attempt.file.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw))).map(x=>x.toString(16).padStart(2,'0')).join('');const body=new FormData();body.set('resourceId',attempt.resource);body.set('idempotencyKey',attempt.key);body.set('sha256',hash);body.set('content',attempt.file);const response=await fetch(c.path+'/upload',{method:'POST',headers:{Authorization:'Bearer '+await accessToken()},body});if(!response.ok)throw Error();const doc=await response.json();if(typeof doc.documentId!=='string'||doc.sha256!==hash)throw Error();if(run!==epoch)return;pending=null;status.value='Document uploaded';busy.value=false;await list();}catch{if(run===epoch){error.value='Upload failed or access denied; the same unchanged file may be retried';status.value='';}}finally{if(run===epoch)busy.value=false;}}
async function download(doc:Doc){const run=epoch;busy.value=true;error.value='';try{const response=await fetch(c.path+'/download',{method:'POST',headers:{Authorization:'Bearer '+await accessToken(),'Content-Type':'application/json'},body:JSON.stringify({resourceId:resource.value,documentId:doc.documentId})});if(!response.ok)throw Error();const raw=await response.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw))).map(x=>x.toString(16).padStart(2,'0')).join('');if(hash!==doc.sha256||raw.byteLength!==doc.size)throw Error();if(run!==epoch)return;const url=URL.createObjectURL(new Blob([raw],{type:'application/octet-stream'}));const a=document.createElement('a');try{a.href=url;a.download=doc.filename;a.click();}finally{URL.revokeObjectURL(url);}status.value='Downloaded bytes verified';}catch{error.value='Download unavailable or integrity verification failed';}finally{busy.value=false;}}
</script>
<template><section aria-label="Documents" class="document-panel"><h2>Documents</h2><form @submit.prevent="list"><label>Document resource<input v-model="resource" @input="reset" maxlength="128" /></label><button :disabled="busy">Load attachments</button></form><form @submit.prevent="upload"><label>Document file<input type="file" accept="text/plain,.txt" @change="choose" :disabled="busy" /></label><button :disabled="busy">Upload document</button></form><p role="status">{{status}}</p><p v-if="busy" role="status">Loading documents</p><p v-if="error" role="alert">{{error}}</p><p v-if="!busy&&!error&&rows.length===0">No attachments loaded</p><ul aria-label="Attachment list"><li v-for="doc in rows" :key="doc.documentId"><strong>{{doc.filename}}</strong> — {{doc.size}} bytes <code>{{doc.sha256}}</code><time>{{doc.createdAt}}</time><button :disabled="busy" @click="download(doc)">Download {{doc.filename}}</button></li></ul></section></template>
<style scoped>.document-panel{border-top:1px solid;margin-top:2rem;padding-top:1rem}form{display:flex;gap:1rem;flex-wrap:wrap;margin:.75rem 0}label{display:flex;flex-direction:column}li{margin:1rem 0;overflow-wrap:anywhere}code,time{display:block}button:focus-visible,input:focus-visible{outline:3px solid #185abc;outline-offset:2px}@media(max-width:40rem){form>*{flex:1 1 100%}}</style>
